#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto create_segment_tree = [](int size) {
        int i = 2;
        while (true) {
            if (i >= size * 2) {
                return vector<long long>(i, 0);
            }
            i *= 2;
        }
    };

    auto update_node = [](vector<long long>& tree, int len, int i, long long value) {
        int idx = i + len / 2;
        tree[idx] = value;
        idx /= 2;
        while (idx > 0) {
            tree[idx] = tree[2 * idx] + tree[2 * idx + 1];
            idx /= 2;
        }
    };

    auto get_range_sum = [](const vector<long long>& tree, int len, int s, int t) {
        s += len / 2;
        t += len / 2;
        long long total = 0;
        while (s <= t) {
            if (s % 2 == 0) {
                s /= 2;
            } else {
                total += tree[s];
                s = (s + 1) / 2;
            }
            if (t % 2 == 1) {
                total += tree[t];
                t = (t - 1) / 2;
            } else {
                t /= 2;
            }
        }
        return total;
    };

    auto prime_factorization = [](long long n) {
        std::vector<long long> factors;
        for (long long i = 2; i * i <= n; ++i) {
            while (n % i == 0) {
                factors.push_back(i);
                n /= i;
            }
            if (n == 1) break;
        }
        if (n != 1) {
            factors.push_back(n);
        }
        return factors;
    };

    auto compute_phi = [&](long long n) {
        std::set<long long> p_factors;
        for (auto p : prime_factorization(n)) {
            p_factors.insert(p);
        }
        long long result = n;
        for (auto p : p_factors) {
            result = result * (p - 1) / p;
        }
        return result;
    };

    auto factorial_mod_range = [&](long long a, long long b, long long mod) {
        long long res = 1;
        for (long long i = a + 1; i <= b; ++i) {
            res = (res * i) % mod;
        }
        return res;
    };

    int n;
    long long mod;
    cin >> n >> mod;

    long long phi_value = compute_phi(mod);
    int max_len = n + 5;
    std::vector<long long> fact_list(max_len + 1, 1);
    for (int i = 1; i <= max_len; ++i) {
        fact_list[i] = (fact_list[i - 1] * i) % mod;
    }

    if (n <= 3) {
        cout << 0 << "\n";
        return 0;
    }

    std::vector<long long> dp(2000, 0);
    dp[0] = 1; dp[1] = 2; dp[2] = 2; dp[3] = 1;

    int size_tree = 2005;
    auto tree = create_segment_tree(size_tree);
    for (int i = 0; i < 4; ++i) {
        update_node(tree, size_tree, i, dp[i]);
    }

    int m = 3;
    long long total_answer = 0;

    for (int i = 0; i < n - 3; ++i) {
        std::vector<long long> prev_dp = dp;
        long long partial_sum_value = 0;
        for (int j = 0; j <= i + 2; ++j) {
            for (int k = 1; k <= m + 1; ++k) {
                long long sum_range = get_range_sum(tree, size_tree, j + k + 1, 2004);
                long long val = (sum_range * prev_dp[k - 1]) % mod;
                partial_sum_value = (partial_sum_value + val) % mod;
                dp[j + k] = (dp[j + k] + prev_dp[k - 1]) % mod;
                update_node(tree, size_tree, j + k, dp[j + k]);
            }
        }
        m += i + 3;
        long long range_product = factorial_mod_range(i + 4, n, mod);
        total_answer = (total_answer + (range_product * partial_sum_value) % mod) % mod;
    }

    cout << total_answer << "\n";

    return 0;
}
